import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { ShoppingCart } from 'lucide-react';
import '../App.css';

export default function PaginaInicial() {
  const navigate = useNavigate();

  const [usuarioLogado, setUsuarioLogado] = useState(null);
  const [tenis, setTenis] = useState([]);
  const [categoriaSelecionada, setCategoriaSelecionada] = useState('');
  const [termoPesquisa, setTermoPesquisa] = useState('');

  useEffect(() => {
    const usuario = JSON.parse(localStorage.getItem('usuario'));
    if (!usuario) {
      navigate('/login');
    } else {
      setUsuarioLogado(usuario);
    }
  }, []);

  useEffect(() => {
    buscarTenis();
  }, [categoriaSelecionada, termoPesquisa]);

  const buscarTenis = async () => {
    try {
      const resposta = await axios.get('http://localhost:5000/livros');
      const lista = resposta.data;

      const filtrados = lista.filter((item) => {
        const correspondeCategoria = categoriaSelecionada ? item.categoria === categoriaSelecionada : true;
        const correspondePesquisa = termoPesquisa ? item.nome.toLowerCase().includes(termoPesquisa.toLowerCase()) : true;
        return correspondeCategoria && correspondePesquisa;
      });

      setTenis(filtrados);
    } catch (erro) {
      console.error('Erro ao buscar tênis:', erro);
    }
  };

  const categoriasUnicas = Array.from(new Set(tenis.map(item => item.categoria))).filter(Boolean);

  const handleAdicionarAoCarrinho = async (tenisId) => {
    try {
      await axios.post('http://localhost:5000/carrinho', {
        usuario_id: usuarioLogado.id,
        livro_id: tenisId
      });
      alert('Tênis adicionado ao carrinho!');
    } catch (erro) {
      console.error('Erro ao adicionar ao carrinho:', erro);
      alert('Erro ao adicionar ao carrinho.');
    }
  };

  return (
    <div className="pagina-inicial">
      <div className="header">
        <h1>Loja de Tênis</h1>
        <div className="botoes-topo">
          <button className="botao-perfil" onClick={() => navigate(`/perfil/${usuarioLogado?.id}`)}>Perfil</button>
          <button className="botao-adicionar" onClick={() => navigate('/adicionar')}>Adicionar Tênis</button>
          <button className="botao-carrinho topo" onClick={() => navigate('/carrinho')}>
            <ShoppingCart className="icone-carrinho" />
          </button>
        </div>
      </div>

      <div className="filtros-container">
        <input
          type="text"
          placeholder="Pesquisar tênis..."
          value={termoPesquisa}
          onChange={(e) => setTermoPesquisa(e.target.value)}
          className="barra-pesquisa"
        />
        <select
          value={categoriaSelecionada}
          onChange={(e) => setCategoriaSelecionada(e.target.value)}
          className="select-categoria"
        >
          <option value="">Todas as categorias</option>
          {categoriasUnicas.map((categoria, index) => (
            <option key={index} value={categoria}>{categoria}</option>
          ))}
        </select>
      </div>

      <div className="lista-produtos">
        {tenis.map((item) => (
          <div className="card-produto" key={item.id} onClick={() => navigate(`/produto/${item.id}`)}>
            <img
              src={item.imagem_url}
              alt={item.nome}
              className="imagem-produto"
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = 'https://via.placeholder.com/300x200?text=Imagem+Indisponível';
              }}
            />
            <h3>{item.nome}</h3>
            <p>{item.autor}</p>
            <button
              className="botao-carrinho card"
              onClick={(e) => {
                e.stopPropagation();
                handleAdicionarAoCarrinho(item.id);
              }}
            >
              <ShoppingCart className="icone-carrinho" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
